"""Dependency-free AMUN Studio identity constants."""

from pathlib import Path


STUDIO_DIRECTORY = Path(__file__).resolve().parent
BRAND_MARK_256 = STUDIO_DIRECTORY / "assets" / "amun-mark-256.png"
BRAND_MARK_64 = STUDIO_DIRECTORY / "assets" / "amun-mark-64.png"

BRAND_MIDNIGHT = "#071A36"
BRAND_LAPIS = "#0A2F78"
BRAND_GOLD = "#E6B84B"
BRAND_PAPYRUS = "#F3E8CB"
BRAND_OBSIDIAN = "#090B0D"

# Platform metal-tier trophies (small UI sizes). Generated by
# scripts/make_metal_tiers.py from the shared palette in compiler/metal_tiers.py.
METAL_TIER_DIRECTORY = STUDIO_DIRECTORY / "assets" / "metal-tiers"
METAL_TIER_SLUGS = ("copper", "bronze", "silver", "electrum", "gold", "platinum", "rhodium")


def metal_tier_icon(slug: str, size: int = 16) -> Path:
    return METAL_TIER_DIRECTORY / f"{slug}-{size}.png"
